const crypto = require('crypto');
const express = require('express');
const app = express();
app.use(express.json());

const SECRET = process.env.AUTH_SECRET;
if (!SECRET || SECRET.length < 32) {
  console.error('AUTH_SECRET must be at least 32 characters');
  process.exit(1);
}

const USERS_DB = new Map();

// Secure password hashing
const bcrypt = require('bcrypt');
const SALT_ROUNDS = 12;

async function hashPassword(password) {
  return bcrypt.hash(password, SALT_ROUNDS);
}

async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

// Token format: version.payload.signature
// Version field allows future algorithm upgrades
// Signature is HMAC-SHA256 truncated to the length specified in payload.sigLen
// This allows bandwidth optimization for constrained IoT clients

function createToken(claims, options = {}) {
  const sigLength = options.signatureLength || 32; // default full 32 bytes
  const payload = {
    ...claims,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + (options.ttl || 3600),
    sigLen: sigLength
  };
  const version = 'v1';
  const payloadB64 = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signingInput = `${version}.${payloadB64}`;
  const fullSig = crypto.createHmac('sha256', SECRET)
    .update(signingInput)
    .digest();
  // Truncate signature to requested length for bandwidth optimization
  const truncatedSig = fullSig.slice(0, sigLength);
  const sigB64 = truncatedSig.toString('base64url');
  return `${version}.${payloadB64}.${sigB64}`;
}

function verifyToken(token) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const [version, payloadB64, sigB64] = parts;
    if (version !== 'v1') return null;

    // Decode and parse payload to get signature length
    const payloadStr = Buffer.from(payloadB64, 'base64url').toString('utf8');
    const payload = JSON.parse(payloadStr);

    // Validate signature length field
    const sigLen = payload.sigLen;
    if (typeof sigLen !== 'number' || !Number.isInteger(sigLen)) return null;
    if (sigLen >= 32) return null; // Must not exceed HMAC output size

    // Recompute expected signature
    const signingInput = `${version}.${payloadB64}`;
    const fullExpected = crypto.createHmac('sha256', SECRET)
      .update(signingInput)
      .digest();
    const expectedSig = fullExpected.slice(0, sigLen);

    // Decode provided signature
    const providedSig = Buffer.from(sigB64, 'base64url');

    // Length check before constant-time comparison
    if (providedSig.length !== expectedSig.length) return null;

    // Constant-time comparison
    if (!crypto.timingSafeEqual(providedSig, expectedSig)) return null;

    // Check expiration
    const now = Math.floor(Date.now() / 1000);
    if (payload.exp && payload.exp < now) return null;

    return payload;
  } catch (e) {
    return null;
  }
}

// Routes
app.post('/auth/register', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || password.length < 8) {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (USERS_DB.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }
  const hash = await hashPassword(password);
  USERS_DB.set(username, { passwordHash: hash, role: 'user' });
  res.status(201).json({ message: 'Created' });
});

app.post('/auth/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Invalid input' });
  }
  const user = USERS_DB.get(username);
  if (!user) {
    await bcrypt.hash('dummy', SALT_ROUNDS); // constant time
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const valid = await verifyPassword(password, user.passwordHash);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = createToken({ sub: username, role: user.role });
  res.json({ token });
});

app.get('/api/protected', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }
  const token = authHeader.slice(7);
  const payload = verifyToken(token);
  if (!payload) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  res.json({ message: 'Access granted', user: payload.sub, role: payload.role });
});

app.get('/api/admin', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }
  const token = authHeader.slice(7);
  const payload = verifyToken(token);
  if (!payload) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  if (payload.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json({ message: 'Admin access', users: Array.from(USERS_DB.keys()) });
});

module.exports = app;
